def counts(text):
    b=s=0
    for line in text.split('## Resolution')[0].splitlines():
        m=re.match(r'^###\s+\d+\.\s+(blocker|should fix)\b',line,re.I) or re.match(r'^\d+\.\s+\*\*(blocker|should fix)\b',line,re.I) or re.match(r'^\|\s*\d+\s*\|\s*(blocker|should fix)\s*\|',line,re.I)
        if m:
            if m[1].lower()=='blocker':b+=1
            else:s+=1
    return b,s
